package com.coffeeshop.service;import com.coffeeshop.model.DocumentModels;import com.coffeeshop.repository.DocumentRepository;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DocumentServiceTest{private final Stub repo=new Stub();private final DocumentService service=new DocumentService(repo);@Test void issuesSupportedDocuments(){service.issue(2,"receipt",3);assertEquals("RECEIPT",repo.type);service.issue(2,"INVOICE",3);assertEquals("INVOICE",repo.type);}@Test void rejectsInvalidInput(){assertThrows(IllegalArgumentException.class,()->service.issue(0,"RECEIPT",1));assertThrows(IllegalArgumentException.class,()->service.issue(1,"CREDIT_NOTE",1));assertThrows(IllegalArgumentException.class,()->service.issue(1,"RECEIPT",0));}private static final class Stub implements DocumentRepository{String type;public DocumentModels.Catalog load(){return new DocumentModels.Catalog(List.of(),List.of());}public long issue(long o,String t,long u){type=t;return 1;}}}
